return {rwnpc01={id="rwnpc01",baseId="rwnpc05",combatid={1,1001},name="村长",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"313002",1}},{type="doc",args={"YEL村长：实不相瞒，我确实略懂些玄门秘术，那画皮也是我亲手封印。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：但也是无奈，那画皮生前是误入林中失了方向，待我们找到她时，她的孩子也已夭折。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：许是深受打击，她精神癫狂，一个劲的说是我们害了她，最后竟自己剥了皮，失血而亡。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：但她似乎也未曾消停，常在村中作祟，不得已，我只能将她封印，希望她有朝一日忘却仇怨。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：唉，未曾想她如今破除封印而出，仇怨不减反增，又害人无数，必须该将它除掉了。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：她很是狡猾，我们只有用她的孩子作饵，诱她现身。在白日即使处于林中，她也受到压制，当趁此机会将她除掉。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL村长：村民们已各自安顿好，少侠落脚的院子已不安全，还是待在祭坛这边吧。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：这妖鬼邪祟，纵使少侠武功高强，只怕也是难以应付，不如就在此好生休息。NOR"}},{type="showbutton",args={3,1}}},caozuoName3="留在此处",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"313008",1}},{type="gaintab",args={"313002",2}},{type="gaintab",args={"313001",1}},{type="doc",args={"CYN你思虑片刻，决定留在此处，或许可以有别的发现。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="outgame",args={"hdrole1306"}},{type="outobject",args={"rwnpc01"}},{type="outobject",args={"rwnpc02"}},{type="refresh",args={}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL村长：有少侠相助自然是好的，只是……唉，还请少侠保护好自己，不要受伤了。NOR"}},{type="outobject",args={"rwnpc01"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"313009",1}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc01a={id="rwnpc01a",baseId="rwnpc05",combatid={1,1001},name="村长",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL村长：那小道长说另有准备，不知道跑到哪去了。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL村长：少侠若是准备好，我便开启此阵，诱那画皮女妖前来，将她铲除！NOR"}}},caozuoName2="开启",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"313009",3}},{type="doc",args={"CYN你只见他念叨了几句难懂的咒语，向地上的阵法丢了些东西，忽然就冒起了蓝色的大火，那哀凄的哭声更为痛苦。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="addobject",args={"rwnpc03"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL村长：妖孽休得妖言惑众，明明是你自己深陷欲孽，害死自己，害死孩子，还至今执迷不悟，履犯杀孽，实在天地难容！NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="gaintab",args={"313009",5}},{type="gaintab",args={"313001",1}},{type="doc",args={"YEL村长：让她给跑了，哼，我自有后手。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="outgame",args={"hdrole1306"}},{type="outobject",args={"rwnpc01a"}},{type="refresh",args={}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={