ndition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc03={id="rwnpc03",baseId="rwnpc36",combatid={1,100044},name="画皮",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL画皮：好歹毒的心思，好歹毒的手段……NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL画皮：剥我皮，压我骨，叫我投胎不得……如今还要用我的孩儿要挟我！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL画皮：纵使魂飞魄散，我也要拉你们一起同往！NOR"}}},caozuoName2="降伏",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="challenge",args={"rwnpc03"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengewin",args={"rwnpc03"}}}},autoResult1={{type="gaintab",args={"313009",4}},{type="doc",args={"CYN眼见可以将画皮逼到阵法中，她却忽然消失了。NOR"}},{type="outobject",args={"rwnpc03"}},{type="outobject",args={"rwwp06_03"}},{type="refresh",args={}}},autoCondition2={relation="and",conditions={{type="challengelose",args={"rwnpc03"}}}},autoResult2={{type="gaintab",args={"313009",4}},{type="doc",args={"YEL画皮：好戏才刚刚开场！NOR"}},{type="outobject",args={"rwnpc03"}},{type="outobject",args={"rwwp06_03"}},{type="refresh",args={}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}